"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[79379],{3331:(i,e,a)=>{a.d(e,{R:()=>r,x:()=>l});var o=a(36672);const n={},t=o.createContext(n);function r(i){const e=o.useContext(t);return o.useMemo((function(){return"function"==typeof i?i(e):{...e,...i}}),[e,i])}function l(i){let e;return e=i.disableParentContext?"function"==typeof i.components?i.components(n):i.components||n:r(i.components),o.createElement(t.Provider,{value:e},i.children)}},19920:(i,e,a)=>{a.r(e),a.d(e,{assets:()=>s,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"2023/04/10","title":"2023-04-10","description":"L\'effetto LLama: La fuga di notizie ha dato il via a una serie di alternative open source a ChatGPT","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/04/10.md","sourceDirName":"2023/04","slug":"/2023/04/10","permalink":"/it/2023/04/10","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/04/10.md","tags":[],"version":"current","frontMatter":{"localized_date":"10 aprile 2023","top_news":"L\'effetto LLama: La fuga di notizie ha dato il via a una serie di alternative open source a ChatGPT"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-11","permalink":"/it/2023/04/11"},"next":{"title":"2023-04-09","permalink":"/it/2023/04/09"}}');var n=a(23420),t=a(3331);const r={localized_date:"10 aprile 2023",top_news:"L'effetto LLama: La fuga di notizie ha dato il via a una serie di alternative open source a ChatGPT"},l="2023-04-10",s={},c=[{value:"L&#39;effetto LLama: La fuga di notizie ha dato il via a una serie di alternative open source a ChatGPT",id:"leffetto-llama-la-fuga-di-notizie-ha-dato-il-via-a-una-serie-di-alternative-open-source-a-chatgpt",level:2},{value:"Dall&#39;apprendimento profondo a quello lungo?",id:"dallapprendimento-profondo-a-quello-lungo",level:2},{value:"EY viene bandita da nuove attivit\xe0 di revisione contabile in Germania",id:"ey-viene-bandita-da-nuove-attivit\xe0-di-revisione-contabile-in-germania",level:2},{value:"Tramonto al Polo Sud",id:"tramonto-al-polo-sud",level:2},{value:"Giornalista olandese che scrive in modo critico sulla Cina preso di mira in un piano di intimidazione",id:"giornalista-olandese-che-scrive-in-modo-critico-sulla-cina-preso-di-mira-in-un-piano-di-intimidazione",level:2},{value:"La struttura USPS nello Utah non fa altro che decifrare la calligrafia.",id:"la-struttura-usps-nello-utah-non-fa-altro-che-decifrare-la-calligrafia",level:2},{value:"Apple continua a impegnarsi per evitare che i negozi al dettaglio si sindacalizzino",id:"apple-continua-a-impegnarsi-per-evitare-che-i-negozi-al-dettaglio-si-sindacalizzino",level:2},{value:"PL/Rust 1.0: ora un linguaggio affidabile per Postgres",id:"plrust-10-ora-un-linguaggio-affidabile-per-postgres",level:2},{value:"Twitter blocca i like e i retweet che menzionano Substack",id:"twitter-blocca-i-like-e-i-retweet-che-menzionano-substack",level:2},{value:"Z-Library permetter\xe0 agli utenti di condividere libri fisici",id:"z-library-permetter\xe0-agli-utenti-di-condividere-libri-fisici",level:2},{value:"Perseus - Alternativa a NextJS in Rust",id:"perseus---alternativa-a-nextjs-in-rust",level:2},{value:"Un piccolo GPT",id:"un-piccolo-gpt",level:2},{value:"Due tipi di ingegneri del software",id:"due-tipi-di-ingegneri-del-software",level:2},{value:"Programmazione avanzata di Linux (2001)",id:"programmazione-avanzata-di-linux-2001",level:2},{value:"Un CERN per l&#39;IA open source su larga scala",id:"un-cern-per-lia-open-source-su-larga-scala",level:2},{value:"Motore Permafrost - Un motore di gioco RTS OpenGL scritto in C",id:"motore-permafrost---un-motore-di-gioco-rts-opengl-scritto-in-c",level:2},{value:"Chiusura di una connessione SSH obsoleta.",id:"chiusura-di-una-connessione-ssh-obsoleta",level:2},{value:"Flatcar Container Linux",id:"flatcar-container-linux",level:2},{value:"Microsoft / JARVIS: un sistema per connettere i LLM con la comunit\xe0 ML",id:"microsoft--jarvis-un-sistema-per-connettere-i-llm-con-la-comunit\xe0-ml",level:2},{value:"Il tokamak sferico raggiunge temperature di plasma cruciali",id:"il-tokamak-sferico-raggiunge-temperature-di-plasma-cruciali",level:2},{value:"Le prime &quot;uova di Pasqua&quot; del gioco sono state un atto di ribellione aziendale.",id:"le-prime-uova-di-pasqua-del-gioco-sono-state-un-atto-di-ribellione-aziendale",level:2},{value:"Errori modulari in Rust",id:"errori-modulari-in-rust",level:2},{value:"68-95-99.7 Regola",id:"68-95-997-regola",level:2},{value:"UnicodePlots",id:"unicodeplots",level:2},{value:"Il collezionismo digitale su Instagram si sta esaurendo",id:"il-collezionismo-digitale-su-instagram-si-sta-esaurendo",level:2},{value:"La sentenza che minaccia il futuro delle biblioteche",id:"la-sentenza-che-minaccia-il-futuro-delle-biblioteche",level:2},{value:"Do Kwon ha convertito fondi illeciti da LUNA a Bitcoin",id:"do-kwon-ha-convertito-fondi-illeciti-da-luna-a-bitcoin",level:2},{value:"Intervista con Andrew Kelley (creatore di Zig) (2021)",id:"intervista-con-andrew-kelley-creatore-di-zig-2021",level:2},{value:"Supavisor - un pool di connessioni Postgres scritto in Elixir",id:"supavisor---un-pool-di-connessioni-postgres-scritto-in-elixir",level:2},{value:"Nuove accuse di plagio contro Roy Lichtenstein",id:"nuove-accuse-di-plagio-contro-roy-lichtenstein",level:2}];function d(i){const e={a:"a",del:"del",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...i.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(e.header,{children:(0,n.jsx)(e.h1,{id:"2023-04-10",children:"2023-04-10"})}),"\n",(0,n.jsx)(e.h2,{id:"leffetto-llama-la-fuga-di-notizie-ha-dato-il-via-a-una-serie-di-alternative-open-source-a-chatgpt",children:"L'effetto LLama: La fuga di notizie ha dato il via a una serie di alternative open source a ChatGPT"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://thesequence.substack.com/p/the-llama-effect-how-an-accidental",children:"Originale"}),".\nL'accidentale fuga di notizie su \"Llama\", un modello LLM, ha dato vita a un movimento open source alternativo a modelli come GPT-4 e Cohere, disponibili solo tramite API. Dopo la fuga di notizie, sono stati rilasciati Alpaca, Vicuna, Koala, ColossalChat e ChatLLama, tra gli altri modelli, tutti costruiti sulla base di Llama. Le alternative open-source a questi modelli non hanno mostrato lo stesso livello di prestazioni fino al rilascio di Llama. Il rilascio di Llama si \xe8 rivelato una delle pi\xf9 grandi scintille di innovazione nello spazio LLM open-source, dove si profila una guerra tra distribuzione open-source e basata su API. L'effetto LLama ha dimostrato che l'open source \xe8 un meccanismo di distribuzione praticabile per i modelli fondazionali, e ci sono alcune interessanti fonti di innovazione nello spazio LLM."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35504428",children:"Discussion Service"}),".\nLa fuga di notizie sull'effetto LLama ha dato vita ad alternative open-source a ChatGPT, guadagnando l'attenzione degli esperti di tecnologia. GPT-4 dimostra un'intelligenza pi\xf9 significativa, offrendo capacit\xe0 di ragionamento e di generalizzazione rispetto al suo predecessore, GPT-3. I modelli di solo testo dell'intelligenza artificiale sono in grado di comprendere il ragionamento spaziale e i puzzle, ma \xe8 necessaria una messa a punto manuale. Si discute sull'effettivo livello di apprendimento dei modelli linguistici, con la speranza di un futuro di AI accessibile e democratizzato. La fuga di notizie su LLaMA ha portato all'ottimizzazione open-source su tutte le piattaforme; tuttavia, gli esperti criticano la pirateria del software e la regolamentazione delle aziende di AI. OpenAI potrebbe dover affrontare sfide legali per l'utilizzo di modelli per la formazione di risultati commerciali. L'accuratezza del ChatGPT \xe8 divergente: alcuni lo considerano inutile, mentre altri sostengono che il GPT-4 migliora in alcuni aspetti. Bing/Sydney e ChatGPT hanno personalit\xe0 diverse. Il post non fornisce nuovi fatti tecnologici, ma discute la natura della compressione del testo."]}),"\n",(0,n.jsx)(e.h2,{id:"dallapprendimento-profondo-a-quello-lungo",children:"Dall'apprendimento profondo a quello lungo?"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://hazyresearch.stanford.edu/blog/2023-03-27-long-learning",children:"Originale"}),".\nI ricercatori di Stanford del laboratorio Hazy Research stanno migliorando la lunghezza delle sequenze nei modelli di base dell'apprendimento automatico, con particolare attenzione alla creazione di modelli a tempo quasi lineare per la lunghezza delle sequenze che possono portare a contesti di milioni o addirittura di miliardi. Il modello Hyena ha una scalabilit\xe0 nella lunghezza delle sequenze fino a 2k utilizzando una piccola rete neurale che parametrizza i filtri convoluzionali implicitamente tramite un'altra piccola rete neurale con un tempo di implementazione di O(NlogN). I ricercatori stanno esplorando le matrici di apprendimento e la loro connessione alle applicazioni linguistiche. N.D.T."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35502187",children:"Discussion Service"}),".\nI ricercatori di Stanford esplorano la riduzione dei costi per l'autoattenzione in sequenze lunghe. L'ottimizzazione del calcolo per GPU e co-processori pu\xf2 ottimizzare gli LLM. Scetticismo sui modelli a contesto pi\xf9 lungo, l'accoppiamento degli LLM con altri sistemi pu\xf2 creare nuove soluzioni. Il rilascio del GPT-4 porta a nuove ricerche sulla predizione dei next-token, potenziali progressi nella memoria associativa a lungo termine. La comprensione della rappresentazione K,Q,V \xe8 fondamentale, mentre le RNN e i trasformatori hanno implicazioni per la democratizzazione dell'IA. La lunghezza del contesto pu\xf2 essere considerata una nuova forma di ricerca."]}),"\n",(0,n.jsx)(e.h2,{id:"ey-viene-bandita-da-nuove-attivit\xe0-di-revisione-contabile-in-germania",children:"EY viene bandita da nuove attivit\xe0 di revisione contabile in Germania"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.economist.com/business/2023/04/05/ey-gets-banned-from-new-audit-business-in-germany",children:"Originale"}),".\nEY \xe8 stata bandita per due anni dalla revisione contabile di nuovi clienti quotati in borsa in Germania, in quanto l'APAS, l'autorit\xe0 di vigilanza contabile tedesca, ha emesso una multa di 500.000 euro insieme alla sanzione pi\xf9 severa mai comminata. La decisione, che giunge al termine di un'indagine durata tre anni sul ruolo di EY nello scandalo Wirecard, ha inflitto un duro colpo finanziario e di reputazione al gigante contabile assediato. EY aveva dato a Wirecard un certificato di buona salute fino a quando la societ\xe0 non \xe8 crollata nel 2020 tra le accuse di una massiccia frode finanziaria. Dopo lo scandalo Wirecard, EY ha dichiarato di aver stanziato 2 miliardi di dollari in tre anni per migliorare le revisioni contabili riguardanti la tecnologia e l'individuazione delle frodi, ma \xe8 probabile che nessun revisore riesca a fare sempre bene le cose."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35501937",children:"Discussion Service"}),".\nA Ernst & Young (EY) \xe8 stato vietato di condurre nuove revisioni contabili in Germania a causa di decisioni di revisione errate e del coinvolgimento nello scandalo Wirecard. Le societ\xe0 di consulenza subappaltano personale meno pagato per minimizzare il rischio, ma questo pu\xf2 ritorcersi contro. I revisori forniscono solo una ragionevole sicurezza e non garantiscono che non si verifichino frodi. L'uso dell'automazione e dell'IA pu\xf2 aiutare a rilevare le attivit\xe0 fraudolente. La revisione contabile dovrebbe essere separata dalla consulenza per evitare conflitti di interesse. C'\xe8 un dibattito sul valore delle societ\xe0 di consulenza e sulla necessit\xe0 di avere una \"pelle in gioco\"."]}),"\n",(0,n.jsx)(e.h2,{id:"tramonto-al-polo-sud",children:"Tramonto al Polo Sud"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://brr.fyi/posts/sunset",children:"Originale"}),'.\nAlla stazione del Polo Sud, il sole ruota in un cerchio quasi perfetto in senso antiorario intorno al cielo, senza fare differenza tra "notte" e "giorno". Di conseguenza, il tramonto \xe8 distribuito su diverse settimane e la temperatura scende rapidamente quando il sole \xe8 basso nel cielo, di solito verso la met\xe0 di febbraio. Il post include fotografie di vedute del tramonto da varie direzioni e un video per dimostrare lo strano fenomeno. La stazione osserva anche l\'"ora legale", anche se non c\'\xe8 alcuna differenza visibile tra gli orari in un dato giorno. Il post specifica che la stazione del Polo Sud segue l\'ora della Nuova Zelanda e fornisce altri dati come le fasi del crepuscolo e il primo avvistamento di stelle della stagione.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35500966",children:"Discussion Service"}),".\nUn post di Hacker News mostra bellissime foto del tramonto prima di una notte polare di 6 mesi. Nei commenti si parla di come affrontare la mancanza di luce solare, di regolazione della luce e di costruzione di strutture scientifiche. L'esperimento di Solargraphy \xe8 fallito. La costruzione di strutture al Polo Sud \xe8 impressionante. Discussione sui bizzarri fenomeni del viaggio circolare del sole e sul suo effetto sulle condizioni di vita. L'Antartide \xe8 inospitale e bisogna competere per ottenere una posizione che consenta di vedere il sorgere e il tramontare del sole. I commentatori parlano anche delle difficolt\xe0 respiratorie in condizioni di freddo estremo. L'articolo offre una prospettiva interessante sulla vita e la ricerca in Antartide."]}),"\n",(0,n.jsx)(e.h2,{id:"giornalista-olandese-che-scrive-in-modo-critico-sulla-cina-preso-di-mira-in-un-piano-di-intimidazione",children:"Giornalista olandese che scrive in modo critico sulla Cina preso di mira in un piano di intimidazione"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://nltimes.nl/2023/04/08/dutch-journalist-writes-critically-china-targeted-bizarre-intimidation-scheme",children:"Originale"}),".\nMarije Vlaskamp, una giornalista olandese critica nei confronti della Cina, dall'autunno scorso \xe8 stata presa di mira in un bizzarro piano di intimidazione, che comprendeva minacce di bombe e messaggi che chiedevano di ritrattare un articolo. In passato Vlaskamp ha scritto in modo critico sullo Stato cinese, concentrandosi sull'oppressione degli uiguri e dei dissidenti cinesi nei Paesi Bassi. L'ambasciata cinese all'Aia \xe8 stata presa di mira da un allarme bomba che citava sia la Vlaskamp che Wang Jingyu, uno dei soggetti dei suoi articoli. Mentre gli aggressori di Vlaskamp non cercano di nascondere l'origine cinese della minaccia, l'ambasciata cinese ha negato di essere coinvolta nel rafforzamento degli aggressori."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35501969",children:"Discussion Service"}),".\nUn giornalista olandese preso di mira in un piano di intimidazione; gli utenti di Discussion Service discutono dell'interferenza cinese e invitano i governi a fare di pi\xf9. Le stazioni di polizia cinesi operano nei Paesi Bassi e in altri Paesi, che potrebbero dover indagare da soli sulle cosiddette \"azioni grigie\". I critici sostengono che le azioni della Cina violano la sovranit\xe0 e alcuni politici sono stati minacciati di conseguenza. Gli utenti di Discussion Service discutono del ruolo della Cina nei recenti episodi di minacce di bombe contro giornalisti dissidenti che vivono negli Stati Uniti; dibattiti sul governo cinese e sulle sue azioni nei confronti dei giornalisti occidentali. ASML, un'azienda olandese, appare in un contesto in cui la Cina mira a possedere l'elettronica dell'Occidente."]}),"\n",(0,n.jsx)(e.h2,{id:"la-struttura-usps-nello-utah-non-fa-altro-che-decifrare-la-calligrafia",children:"La struttura USPS nello Utah non fa altro che decifrare la calligrafia."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://kutv.com/news/eye-on-utah/what-happens-to-mail-with-band-handwriting-united-states-postal-service-letter-carrier-usps-mailwoman-mailman-cursive-taught-in-schools-unreadable-print-envelopes-undeliverable-packages-salt-lake-city-utah",children:"Originale"}),".\nLa struttura dell'USPS nello Utah \xe8 specializzata nella decifrazione della scrittura disordinata sulla posta. Questa struttura impiega oltre 90 persone che smistano la posta e utilizzano tecnologie avanzate per elaborarla. La tecnologia utilizzata pu\xf2 persino scansionare e digitalizzare gli indirizzi scritti a mano. Questa struttura dimostra come la tecnologia si stia evolvendo per gestire compiti tradizionali in modo innovativo."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35499641",children:"Discussion Service"}),".\nLa struttura dell'USPS nello Utah \xe8 specializzata nella decifrazione della scrittura corsiva con un software fornito da Eagle e Siemens. Il riconoscimento della scrittura a mano ha rappresentato una sfida per gli impiegati postali e l'intervento umano \xe8 ancora necessario. La discussione su Hacker News tocca l'evoluzione del lavoro e dei salari, la propriet\xe0, i sussidi governativi e i vantaggi della scrittura sui libri. Si ritiene che la comunit\xe0 mormone di Salt Lake City abbia contribuito a creare un gran numero di lettori esperti. Alcuni suggeriscono che l'USPS dovrebbe creare un'applicazione mobile, mentre altri esprimono preoccupazione per le violazioni della privacy con l'uso di dati privati."]}),"\n",(0,n.jsx)(e.h2,{id:"apple-continua-a-impegnarsi-per-evitare-che-i-negozi-al-dettaglio-si-sindacalizzino",children:"Apple continua a impegnarsi per evitare che i negozi al dettaglio si sindacalizzino"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.bloomberg.com/news/newsletters/2023-04-09/apple-aapl-continues-efforts-to-keep-retail-stores-from-unionizing-lg9gjdx2",children:"Originale"}),".\nApple sta cercando di evitare che i suoi negozi al dettaglio vengano sindacalizzati, diversificando al contempo la produzione di prodotti e componenti al di fuori della Cina. Di recente l'azienda ha subito tagli di posti di lavoro e la partenza di un altro dirigente. L'articolo menziona anche l'imminente rilascio delle cuffie per la realt\xe0 mista di Apple."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35503210",children:"Discussion Service"}),".\nApple accusata di tattiche antisindacali, tra cui il trattenimento dei benefit; critiche alle tattiche di negoziazione dei sindacati. Discussione sulle complessit\xe0 della sindacalizzazione e dell'impatto sui lavoratori. Il sondaggio Gallup mostra un crescente interesse per la sindacalizzazione, soprattutto tra i lavoratori di prima linea. Alcuni criticano la bassa retribuzione e la mancanza di benefit dei lavori al dettaglio, mentre altri sostengono che le promozioni basate sulla permanenza e i licenziamenti potrebbero avere un impatto negativo sulle aziende."]}),"\n",(0,n.jsx)(e.h2,{id:"plrust-10-ora-un-linguaggio-affidabile-per-postgres",children:"PL/Rust 1.0: ora un linguaggio affidabile per Postgres"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://tcdi.github.io/plrust/plrust.html",children:"Originale"}),".\nPL/Rust \xe8 un linguaggio procedurale caricabile che consente di scrivere funzioni PostgreSQL in Rust, fornendo l'accesso all'interfaccia di programmazione server di Postgres e a tipi Rust sicuri rispetto alla maggior parte dei tipi di dati incorporati in Postgres; le funzioni PL/Rust sono compilate in codice macchina nativo anzich\xe9 essere interpretate, garantendo le migliori prestazioni. PL/Rust \xe8 ora un linguaggio procedurale affidabile per Postgres su sistemi x86_64 e aarch64 se vengono soddisfatti i requisiti di compilazione, consentendo a PL/Rust di vivere in un universo di Safe Rust; PL/Rust utilizza il proprio driver rustc per applicare lint personalizzati alla funzione LANGUAGE plrust dell'utente per applicare determinati idiomi di codice che sanno non avere problemi di \"I-Unsound\". Per impostazione predefinita, PL/Rust non esegue la compilazione incrociata, ma deve essere installato e abilitato attraverso la configurazione."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35501065",children:"Discussion Service"}),".\nPL/Rust 1.0 ora si affida a Postgres come alternativa per le funzioni di database. I provider cloud RDS e Supabase consentono l'implementazione di PL/Rust. Ha prestazioni eccezionali, ma \xe8 ancora vulnerabile ai problemi. I trigger di eventi e i blocchi DO non sono ancora stati incorporati. Rust ha accesso all'ecosistema di sviluppo, tipi efficienti e prestazioni migliori. Pu\xf2 limitare l'ottimizzazione dei trigger computazionali."]}),"\n",(0,n.jsx)(e.h2,{id:"twitter-blocca-i-like-e-i-retweet-che-menzionano-substack",children:"Twitter blocca i like e i retweet che menzionano Substack"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://flipboard.social/@Flipboard/110161362001035875",children:"Original"}),".\nN/A."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35502684",children:"Discussion Service"}),".\nTwitter blocca i like/retweet che menzionano Substack, causando l'effetto Streisand. Elon Musk accusa Substack di aver saccheggiato il database di Twitter; gli esperti ritengono la dichiarazione priva di senso. Substack nega l'uso improprio delle API di Twitter. Critiche ai risultati di ricerca, ai divieti e alle politiche di utilizzo delle API di Twitter. Preoccupazioni sulla qualit\xe0 della funzione newsfeed di Substack. Evoluzione della concorrenza tra Twitter e Substack, esplorazione di protocolli di microblogging alternativi. Resistenza a non trasformare il problema in spettacolo, richiesta di responsabilit\xe0 da parte della leadership. Dibattiti in corso sull'abuso delle API e sul presunto scraping dei contenuti di Twitter da parte di Substack. Attenzione a non ignorare la situazione dei dipendenti di Substack licenziati."]}),"\n",(0,n.jsx)(e.h2,{id:"z-library-permetter\xe0-agli-utenti-di-condividere-libri-fisici",children:"Z-Library permetter\xe0 agli utenti di condividere libri fisici"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://torrentfreak.com/z-library-plans-to-let-users-share-physical-books-through-z-points-230408/",children:"Originale"}),'.\nZ-Library, il pi\xf9 grande deposito di libri piratati, sta espandendo i suoi servizi per includere un mercato di condivisione di libri fisici, con milioni di utenti in grado di ritirare libri in brossura presso "Z-Point" dedicati in tutto il mondo. Il progetto prevede di organizzare "punti di raccolta e stoccaggio" per i libri che "saranno il collegamento tra coloro che condividono i loro libri e coloro che ne hanno bisogno", il che richieder\xe0 uno spazio di stoccaggio e uno sforzo organizzativo considerevoli, per cui sono benvenuti centri di adempimento e servizi logistici di terze parti. Un annuncio pubblicato sul sito sembra essere serio, con persone che suggeriscono Vietnam, Brasile, Portogallo, Colombia, Iran, Uzbekistan, Nigeria, Spagna, India, Argentina, Egitto, Francia, Etiopia, Cina e Ghana come luoghi ideali per gli Z-Point, e il sito sta attualmente accogliendo feedback per migliorare il suo servizio.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35499065",children:"Discussion Service"}),".\nZ-Library consentir\xe0 agli utenti di condividere libri fisici, ma gli editori potrebbero fare causa alla biblioteca; alcuni suggeriscono di scansionare i libri, modificare le leggi sul copyright o incentivare la scansione dei libri. Alcuni discutono la fattibilit\xe0 e l'impatto sulle case editrici del lancio di un mercato di condivisione di libri nel mondo reale. I modelli di licenza degli e-book hanno conseguenze spiacevoli, che portano alla pirateria come forma di protesta. Le biblioteche private hanno preceduto le biblioteche pubbliche e spesso le hanno prestate."]}),"\n",(0,n.jsx)(e.h2,{id:"perseus---alternativa-a-nextjs-in-rust",children:"Perseus - Alternativa a NextJS in Rust"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://framesurge.sh/perseus/en-US/",children:"Originale"}),".\nPerseus \xe8 un framework Rust per applicazioni web moderne che genera lo stato su richiesta e lo passa a Sycamore, con l'aggiunta di I18n basato su Fluent per funzionalit\xe0 multilingue, plugin per la personalizzazione, il tutto in WebAssembly per alte prestazioni, esportabile e servito staticamente, facile da installare e da usare."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35500528",children:"Discussion Service"}),".\nGli utenti discutono di Perseus, un'alternativa a NextJS basata su Rust, con alcuni che preferiscono JS per lo sviluppo front-end a causa degli strumenti di Rust. Nonostante ci\xf2, le incursioni di Rust nei livelli pi\xf9 bassi dello stack JS suggeriscono un potenziale nell'incorporazione di JS/TS in framework Rust come Perseus. Si discute sui meriti di Rust rispetto a Go: alcuni utenti considerano Rust pi\xf9 adatto alla programmazione di basso livello, mentre altri vedono Go pi\xf9 adatto allo sviluppo web. Il valore di un linguaggio di programmazione dipende da dove si vive e si vuole lavorare. Il rilascio di Perseus attira l'attenzione di persone esperte di tecnologia come possibile alternativa pi\xf9 veloce a Svelte, ma \xe8 criticato per essere difficile da usare nel mondo reale."]}),"\n",(0,n.jsx)(e.h2,{id:"un-piccolo-gpt",children:"Un piccolo GPT"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://twitter.com/karpathy/status/1645115622517542913",children:"Original"}),".\nN/A."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35506069",children:"Discussion Service"}),".\nUn utente di Discussion Service propone di usare le espressioni regolari binarie per le relazioni linguistiche, mentre un altro sostiene il significato e l'intento. Il creatore della baby GPT la paragona alla catena di Markov. Un esperto raccomanda migliori strumenti matematici. Un utente di Discussion Service chiede quali siano le implicazioni per il pubblico in generale. Nessuna novit\xe0 tecnologica o rilascio di rilievo."]}),"\n",(0,n.jsx)(e.h2,{id:"due-tipi-di-ingegneri-del-software",children:"Due tipi di ingegneri del software"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://registerspill.thorstenball.com/p/two-types-of-software-engineers",children:"Originale"}),".\nL'articolo parla di due tipi di ingegneri del software: Il tipo 1, che presume che un problema sia facile se non \xe8 tecnico, e il tipo 2, che presume che sia difficile perch\xe9 coinvolge le persone. Il tipo 1 crede nell'ingegneria con la E maiuscola, mentre il tipo 2 si concentra sulle persone e vede i problemi di ingegneria come se coinvolgessero le persone. Mentre il tipo 1 \xe8 pi\xf9 comune, gli ingegneri di tipo 2 comprendono che l'ingegneria comporta caos e complessit\xe0 e mirano a costruire nonostante queste sfide. L'articolo include alcuni esempi per illustrare le differenze, ma l'autore non ha ancora definito o tracciato con precisione il confine tra i due tipi."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35503784",children:"Discussion Service"}),".\nUna discussione sui due tipi di ingegneri del software, compreso il tipo 3, e sull'importanza di comprendere la gestione del prodotto. Dibattito sul bilanciamento tra innovazione e stabilit\xe0 e sulla necessit\xe0 di una documentazione adeguata. Dicotomia tra affidarsi alle persone e implementare soluzioni automatizzate nell'ingegneria del software. Importanza di allineare tutti su obiettivi comuni e di comprendere le esigenze aziendali pi\xf9 ampie. La categorizzazione degli ingegneri del software \xe8 stata messa in discussione, ponendo l'accento sulla ricerca delle cause dei problemi. Il post serve come spunto di riflessione."]}),"\n",(0,n.jsx)(e.h2,{id:"programmazione-avanzata-di-linux-2001",children:"Programmazione avanzata di Linux (2001)"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://mentorembedded.github.io/advancedlinuxprogramming/",children:"Originale"}),".\nAdvanced Linux Programming\" di CodeSourceryLLC \xe8 un libro che aiuta gli sviluppatori GNU/Linux a creare software con caratteristiche di facile utilizzo, funzionalit\xe0 avanzate come il multi-threading, la comunicazione tra processi e l'interazione con i dispositivi hardware, e il miglioramento generale del programma. Inoltre, questo libro insegna agli sviluppatori come lavorare all'interno dell'ambiente di sistema GNU/Linux, comprese le sue limitazioni, convenzioni e capacit\xe0 uniche. Questo libro \xe8 disponibile per il download secondo la Open Publication License, versione 1, e viene fornito con l'accesso a campioni di codice coperti dalla GNU General Public License. Sono disponibili errori e traduzioni del libro."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35500197",children:"Discussion Service"}),".\nGli utenti di Hacker News discutono della rilevanza del libro del 2001, \"Advanced Linux Programming\", nel 2021. Alcuni utenti suggeriscono di aggiornare le sezioni obsolete. Nonostante sia un libro per principianti, rimane una risorsa utile per lo sviluppo di API Linux. L'applicazione di download Aria2 \xe8 un'alternativa ai limiti di velocit\xe0 dei server."]}),"\n",(0,n.jsx)(e.h2,{id:"un-cern-per-lia-open-source-su-larga-scala",children:"Un CERN per l'IA open source su larga scala"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.openpetition.eu/petition/online/securing-our-digital-future-a-cern-for-open-source-large-scale-ai-research-and-its-safety",children:"Originale"}),".\nLAION e.V. ha lanciato una petizione per la creazione di una struttura di ricerca internazionale, finanziata con fondi pubblici e open source per l'IA, simile al CERN, per democratizzare la ricerca sull'IA e promuovere la ricerca sulla sicurezza. La piattaforma openPetition mira a rafforzare la partecipazione dei cittadini e a sostenere le petizioni per il cambiamento. L'iniziativa mira a proteggere i principi democratici dall'essere minati da poche e selezionate grandi aziende. Un utente di Discussion Service ha notato che il 19% dei sostenitori proviene da laion.ai, mentre il 64% rimane sconosciuto. I cittadini sono incoraggiati a fare una donazione per sostenere la petizione che ha guadagnato terreno su Hacker News."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35501845",children:"Discussion Service"}),".\nUn articolo di openpetition.eu sottolinea la necessit\xe0 per l'Europa di un'iniziativa open source simile al CERN per promuovere la collaborazione tra ricercatori, accademici e imprenditori dell'IA. La collaborazione \xe8 necessaria per eseguire l'elaborazione di grandi dati con grandi investimenti di capitale. I progetti open source sono necessari per trattenere i ricercatori di IA e portare benefici alla societ\xe0 piuttosto che agli azionisti delle aziende. Il successo del CERN lo rende un modello attraente, anche se alcuni ritengono che il mercato fornisca incentivi adeguati. La natura interdisciplinare dell'IA richiede la considerazione di questioni interconnesse."]}),"\n",(0,n.jsx)(e.h2,{id:"motore-permafrost---un-motore-di-gioco-rts-opengl-scritto-in-c",children:"Motore Permafrost - Un motore di gioco RTS OpenGL scritto in C"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/eduard-permyakov/permafrost-engine",children:"Originale"}),".\nPermafrost Engine \xe8 un motore di gioco OpenGL 3.3 Real Time Strategy scritto in C, realizzato a immagine e somiglianza dei vecchi classici ma con alcune idee moderne. EVERGLORY \xe8 il gioco di punta sviluppato con Permafrost Engine, che presenta le capacit\xe0 del motore con un'esperienza di gioco di prima mano. Il riepilogo del motore include un elenco di funzionalit\xe0 OpenGL e Python, meccaniche RTS e funzionalit\xe0 multipiattaforma. La licenza di Permafrost Engine \xe8 GPLv3, con una speciale eccezione per il linking. Vengono fornite istruzioni per la compilazione sia per Linux che per Windows. Per gli utenti interessati sono disponibili un devlog e un'e-mail per domande/commenti sul progetto o sul codice sorgente."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35504053",children:"Discussion Service"}),".\nIl motore open-source Permafrost guadagna attenzione su Discussion Service per un nuovo gioco RTS open-source. Criticata la chiarezza dei caratteri del gioco Everglory. Richiesto un confronto con altri motori RTS. I test degli sviluppatori sugli schermi palmari sono importanti. Speranza per la rinascita del genere RTS. Gli utenti discutono dei motori RTS open-source e dei linguaggi utilizzati. Menzione di un'altra implementazione open-source del motore Frostbite."]}),"\n",(0,n.jsx)(e.h2,{id:"chiusura-di-una-connessione-ssh-obsoleta",children:"Chiusura di una connessione SSH obsoleta."}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://davidisaksson.dev/posts/closing-stale-ssh-connections/",children:"Originale"}),".\nIl post parla di come chiudere una sessione SSH obsoleta, affermando che mentre la prima soluzione potrebbe essere quella di chiudere l'emulatore di terminale, esiste un modo migliore per utilizzare le sequenze di escape integrate in SSH. Il post spiega come il prefisso tilde (",(0,n.jsx)(e.del,{children:') seguito da un comando possa attivare pi\xf9 comandi nascosti nei client SSH, compreso il comando "termina sessione" ('}),'.). Il post fa notare che occorre prestare attenzione al fatto che \xe8 necessario un newline precedente e offre una piccola nota per chi utilizza una tastiera con layout nordico per digitare il carattere tilde. Il post termina con una discussione su cosa fare dopo aver usato la sequenza di escape "termina sessione".']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35504402",children:"Discussion Service"}),".\nUn utente di Discussion Service fornisce un suggerimento su SSH. Un altro fa notare un problema di layout ma fornisce una soluzione. Viene suggerita la configurazione di EscapeChar. Discussione sulla pagina man di SSH, sul salto di host e sulle connessioni SSH. Si auspica una sessione SSH appiccicosa. Si raccomanda Autossh per l'auto-attacco e Mosh per cambiare il port forwarding. Vengono forniti dettagli sulla crittografia e ulteriori suggerimenti. Si raccomanda di non utilizzare Alpine Linux."]}),"\n",(0,n.jsx)(e.h2,{id:"flatcar-container-linux",children:"Flatcar Container Linux"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.flatcar.org/",children:"Originale"}),".\nFlatcar Container Linux \xe8 una distribuzione Linux comunitaria progettata per i carichi di lavoro dei container con elevata sicurezza e bassa manutenzione. L'immagine del sistema operativo include solo gli strumenti necessari per l'esecuzione dei container, senza gestore di pacchetti o derivazioni di configurazione. Il filesystem immutabile e gli aggiornamenti atomici automatizzati forniscono una solida base per la sicurezza dell'infrastruttura. Le funzioni di sicurezza integrate di Flatcar Container Linux e la ridotta superficie di attacco semplificano la gestione del sistema operativo. Include strumenti per gestire infrastrutture su larga scala e supporta iniziative globali. Gli aggiornamenti automatici e atomici garantiscono l'esecuzione della versione di Flatcar pi\xf9 stabile, sicura e aggiornata. \xc8 un sostituto di CoreOS Container Linux."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35503928",children:"Discussion Service"}),".\nL'aggiornamento di Flatcar Container Linux di Microsoft continua anche dopo l'acquisizione, fornendo un'alternativa a CloudInit. L'approccio dell'infrastruttura immutabile guadagna popolarit\xe0 nonostante i problemi tecnici di Ignition. Gli sviluppatori di Flatcar Linux suggeriscono un aggiornamento amichevole. Gli utenti di Discussion Service discutono dell'aggiunta di container e suggeriscono un firmware UEFI per migliorare le prestazioni."]}),"\n",(0,n.jsx)(e.h2,{id:"microsoft--jarvis-un-sistema-per-connettere-i-llm-con-la-comunit\xe0-ml",children:"Microsoft / JARVIS: un sistema per connettere i LLM con la comunit\xe0 ML"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/microsoft/JARVIS",children:"Originale"}),".\nMicrosoft e Hugging Face hanno presentato il progetto di laboratorio JARVIS, un assistente AI per collegare modelli linguistici e di apprendimento automatico. JARVIS utilizza un modello linguistico di grandi dimensioni (LLM) per comprendere e analizzare le richieste, quindi utilizza una selezione di numerosi modelli esperti per eseguire il compito richiesto. Si compone di quattro fasi: pianificazione del compito, selezione del modello, esecuzione del compito e generazione della risposta. L'utente pu\xf2 godere di un'esperienza leggera con JARVIS senza distribuire i modelli localmente, attivando la modalit\xe0 CLI o la pagina web, che mostra un'interfaccia user-friendly che comunica con JARVIS."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35500472",children:"Discussion Service"}),".\nMicrosoft lancia JARVIS per connettere i LLM con la comunit\xe0 ML utilizzando approcci basati su regole e apprendimento automatico. Alcuni ipotizzano che gli agenti AI autonomi possano commettere frodi o truffe, ma i lettori sono soprattutto entusiasti. Jarvis genera testo e immagini in base ai modelli scelti dall'LLM, ma alcuni sollevano dubbi su questioni di marchio e intercettazioni."]}),"\n",(0,n.jsx)(e.h2,{id:"il-tokamak-sferico-raggiunge-temperature-di-plasma-cruciali",children:"Il tokamak sferico raggiunge temperature di plasma cruciali"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.eetimes.com/spherical-tokamak-achieves-crucial-plasma-temperatures/",children:"Originale"}),".\nIl tokamak sferico di Tokamak Energy ha raggiunto temperature di ioni di oltre 100 milioni di gradi Kelvin, un passo fondamentale per lo sviluppo della tecnologia dell'energia di fusione. Le dimensioni ridotte, la stabilit\xe0 del plasma e le propriet\xe0 di confinamento magnetico dei tokamak sferici li rendono una scelta interessante per la produzione commerciale di energia da fusione. Steven McNamara, direttore scientifico di Tokamak Energy, ritiene che l'azienda possa mettere in rete l'energia da fusione entro 10 anni, integrando altre fonti di energia rinnovabile. La scoperta utilizza la diffusione di Thomson per misurare la temperatura e la densit\xe0 in pi\xf9 punti, aprendo la strada a impianti commerciali di energia da fusione a basso costo e distribuibili. La tecnologia ha anche potenziali applicazioni nell'aviazione sostenibile e nella produzione di carburante a idrogeno."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35505342",children:"Discussion Service"}),".\nUn tokamak sferico raggiunge temperature di plasma cruciali. Alcuni utenti discutono i problemi strutturali, uno consiglia un podcast sull'energia da fusione. L'articolo spiega la necessit\xe0 di uno scambiatore di calore e i costi ridotti del nuovo progetto. Si discute sulla fattibilit\xe0 della fusione commerciale. Il raddoppio della forza del magnete nei test su piccola scala fa avanzare i progressi. I vantaggi della fusione rispetto alla fissione in termini di rifiuti e di sicurezza. I tokamak sferici sono un'applicazione all'avanguardia. La pietra miliare raggiunta non \xe8 ancora utile, ma si fanno progressi sulla forza del magnete."]}),"\n",(0,n.jsx)(e.h2,{id:"le-prime-uova-di-pasqua-del-gioco-sono-state-un-atto-di-ribellione-aziendale",children:'Le prime "uova di Pasqua" del gioco sono state un atto di ribellione aziendale.'}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://thehustle.co/the-first-easter-eggs-were-an-act-of-corporate-rebellion/",children:"Originale"}),".\nLe prime uova di Pasqua nei videogiochi furono il risultato del fatto che ai progettisti fu negato il credito per il loro lavoro, il che port\xf2 a messaggi nascosti nei giochi. Il primo uovo di Pasqua fu trovato nel gioco \"Adventure\" di Atari del 1980, creato da Warren Robinett. La tradizione dei messaggi nascosti continu\xf2 nei giochi arcade degli anni '70 per cercare riconoscimento e individualit\xe0. L'uovo di Pasqua di Robinett ha elevato il suo status e ha continuato a sviluppare un'attivit\xe0 di software di successo. Il Tech Times riferisce di vari cookie utilizzati dalle aziende per tracciare il comportamento online degli utenti e personalizzare gli annunci, ma non sono ancora stati classificati."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35503260",children:"Discussion Service"}),".\nUn post di Hacker News sulla ribellione aziendale attraverso le uova di Pasqua presenta aneddoti e politiche aziendali attuali. L'interesse dei lettori pu\xf2 essere suscitato dalla rilevanza storica e dall'evoluzione del ruolo dell'uovo di Pasqua. Le attuali uova di Pasqua esprimono orgoglio aziendale, non insubordinazione. Le revisioni del codice impediscono le uova di Pasqua. Le ex aziende tecnologiche sono spesso sottoposte a MBA di nuova nomina. Warren Robinett viene elogiato per Adventure game. Il membro degli U2 e il fan di Atari hanno nomi diversi."]}),"\n",(0,n.jsx)(e.h2,{id:"errori-modulari-in-rust",children:"Errori modulari in Rust"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://sabrinajewson.org/blog/errors",children:"Originale"}),".\nL'articolo discute l'importanza della gestione modulare degli errori e introduce il principio secondo cui i tipi di errore sono vicini alla loro unit\xe0 di fallibilit\xe0, utilizzando un'ipotetica libreria Rust come esempio. Vengono delineati i problemi legati ai messaggi di errore non utili, all'inestensibilit\xe0 e alla difficolt\xe0 di corrispondenza degli errori, e vengono suggerite soluzioni come il metodo .source() e una migliore costruzione dei tipi di errore. Il tipo di errore della libreria di esempio viene suddiviso in tre tipi distinti, con buoni backtraces e una precisa corrispondenza degli errori, e gli errori di I/O vengono spiegati attraverso una progettazione pi\xf9 strutturata dei tipi di errore. L'articolo sottolinea l'importanza di buone backtraces, estensibilit\xe0, ispezionabilit\xe0, stabilit\xe0 e modularit\xe0 nella gestione degli errori e suggerisce che vale la pena imparare una buona gestione degli errori."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35502874",children:"Discussion Service"}),".\nI messaggi di errore di Rust sono popolari, ma sono necessari tipi di errore diversi. SNAFU consente di produrre tracce uniche. Gli errori distinti riducono la proliferazione e facilitano la gestione, ma bisogna fare attenzione al supporto di API pubbliche. La registrazione e la terminazione non dovrebbero essere l'approccio principale per il debug delle librerie. Sono preferibili errori granulari o opachi con descrizioni. Le eccezioni controllate in Java sono apprezzate. Il difetto fatale di Java \xe8 l'assenza di tipi algebrici."]}),"\n",(0,n.jsx)(e.h2,{id:"68-95-997-regola",children:"68-95-99.7 Regola"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://en.wikipedia.org/wiki/68%E2%80%9395%E2%80%9399.7_rule",children:"Original"}),".\nLa regola del 68-95-99,7 \xe8 un'approssimazione statistica che stima la percentuale di valori entro una deviazione standard dalla media nella distribuzione normale. La regola afferma che circa il 68%, il 95% e il 99,7% rientrano rispettivamente in una, due e tre deviazioni standard. Questa regola ha molteplici utilizzi in diversi campi, come il controllo di qualit\xe0 e l'analisi dei dati. \xc8 un modo rapido per ottenere una stima approssimativa della probabilit\xe0 per una popolazione che si presume normale. La formula pu\xf2 essere applicata a diverse distribuzioni e pu\xf2 aiutare a identificare gli outlier nell'analisi dei dati."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35501780",children:"Discussion Service"}),".\nI commenti di Discussion Service discutono i limiti della regola 68-95-99,7 nell'analisi dei dati. Vengono citati il lavoro di Nassim Nicholas Taleb e la disuguaglianza di Chebyshev. Tangenti sul trading finanziario e sulla storia del mercato delle opzioni negli Stati Uniti. Gli utenti esperti sostengono che i punteggi del QI sono inaffidabili e che la scala \xe8 arbitraria."]}),"\n",(0,n.jsx)(e.h2,{id:"unicodeplots",children:"UnicodePlots"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/JuliaPlots/UnicodePlots.jl",children:"Originale"}),".\nLa libreria UnicodePlots \xe8 uno strumento di plottaggio di alto livello da usare nella REPL di Julia, che include grafici a dispersione, grafici a linee e mappe di calore. Supporta anche le grandezze fisiche di Unitful.jl e gli intervalli di IntervalSets.jl, consente la personalizzazione delle caratteristiche del grafico, come l'altezza e la larghezza del grafico e l'inversione/ribaltamento degli assi del grafico, e supporta il salvataggio dei grafici in formato PNG o TXT."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35505591",children:"Discussion Service"}),".\nUnicodePlots, basato su Julia, mostra grafici e istogrammi sul terminale per una rapida visualizzazione su server remoti. Risponde all'esigenza di visualizzare rapidamente i dati nel terminale, senza installare uno stack grafico completo. UnicodePlots \xe8 stato copiato soprattutto in una versione Ruby e in una versione Python compatibile con Matplotlib. Attualmente c'\xe8 una tendenza verso le interfacce utente testuali, creando una divisione tra Electron per le applicazioni dell'utente finale e TUI per gli strumenti portatili. Ha una copertura del codice del 100%, supporta istogrammi comparativi e consente agli utenti di copiare e incollare i dati direttamente nei commenti o nelle descrizioni. Pur non essendo una tecnologia completamente nuova, UnicodePlots \xe8 uno strumento utile per chi ha bisogno di valutare rapidamente i dati."]}),"\n",(0,n.jsx)(e.h2,{id:"il-collezionismo-digitale-su-instagram-si-sta-esaurendo",children:"Il collezionismo digitale su Instagram si sta esaurendo"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://help.instagram.com/1824155514623095",children:"Original"}),".\nA partire dall'11 aprile 2023, Instagram cesser\xe0 di supportare i collezionabili digitali, con ripercussioni sulla creazione di nuovi post di collezionabili digitali, sulla visibilit\xe0 dei portafogli digitali e sull'accessibilit\xe0 delle informazioni della blockchain. L'eliminazione dei dati degli oggetti da collezione digitali avverr\xe0 in conformit\xe0 con l'Informativa sulla privacy e i Termini d'uso degli oggetti da collezione digitali di Instagram, ma gli utenti possono presentare una richiesta per scaricare le proprie informazioni prima della scadenza. I contenuti dei portafogli digitali di terze parti non saranno interessati."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35501074",children:"Discussion Service"}),".\nIl collezionismo digitale di Instagram sta perdendo colpi, ma i sostenitori di Web3 non si lasciano scoraggiare. Lo spazio NFT deve affrontare gli standard di propriet\xe0 e l'adozione commerciale. Gli avatar di Reddit vendono bene, ma i NFT poligonali sono percepiti come meno preziosi. L'inverno \xe8 il benvenuto per i costruttori che costruiscono infrastrutture e per le imprese tradizionali che imparano a conoscere le reti decentralizzate. Il successo delle carte Pokemon e delle funzionalit\xe0 di Reddit viene confrontato con il concetto di scarsit\xe0. L'espressione \"Web3\" potrebbe essere prematura e truffatori e costruttori sono in campi diversi. C'\xe8 scetticismo e preoccupazione per l'hype di NFT, i rischi di investimento e la salute mentale. Si discute del coinvolgimento dei culti nelle industrie, delle criptovalute e dei rischi dell'IA. L'utilit\xe0 della ChatGPT \xe8 discussa e gli utenti si concentrano su approfondimenti freschi senza linguaggio politico o religioso. Viene discusso il contesto della tecnologia avanzata in relazione alla comunicazione e alla sincronizzazione terrestre, con opinioni diverse sul valore delle NFT e sul loro impatto sulla societ\xe0."]}),"\n",(0,n.jsx)(e.h2,{id:"la-sentenza-che-minaccia-il-futuro-delle-biblioteche",children:"La sentenza che minaccia il futuro delle biblioteche"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.theatlantic.com/ideas/archive/2023/04/internet-archive-libraries-federal-court-ruling/673615/",children:"Originale"}),".\nUna sentenza del tribunale federale, secondo cui il prestito digitale controllato (CDL) viola la legge sul copyright, potrebbe avere implicazioni disastrose per le biblioteche, che dovrebbero scegliere tra l'acquisto di costose licenze per gli ebook dagli editori o l'espansione delle loro collezioni; Internet Archive (IA), un'organizzazione senza scopo di lucro che presta copie digitali dei milioni di libri che ha raccolto e digitalizzato, \xe8 stata al centro di un'azione legale da parte di diversi editori di libri che l'hanno citata in giudizio nel 2020 per violazione del copyright; Il mese scorso il tribunale ha condannato questo modello di prestito CDL, che potrebbe avere \"un potere sleale sul futuro dei libri e delle biblioteche\", secondo l'avvocato Corynne McSherry della Electronic Frontier Foundation, che rappresenta l'IA nel suo appello contro la sentenza."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35502238",children:"Discussion Service"}),".\nLa sentenza del tribunale sul prestito digitale controllato e le leggi sul diritto d'autore ha scatenato dibattiti, con la proposta di ridurre la durata del copyright per evitare la perdita di conoscenza; alcuni suggeriscono che i profitti degli editori non dovrebbero essere il problema del prestito di materiale CDL. Le biblioteche si sono adattate a diventare centri di intrattenimento pubblico e l'accesso del pubblico alle risorse \xe8 fondamentale; i bibliotecari usano il parere di esperti per bilanciare la popolarit\xe0 della circolazione, il valore dei libri e la missione della biblioteca quando scartano i libri. Le cause intentate dagli editori contro la distribuzione digitale illimitata e gratuita di Internet Archive compromettono i guadagni degli scrittori e il prestito digitale controllato potrebbe mettere in pericolo la protezione delle leggi sul copyright. L'intersezione tra propriet\xe0 digitale e fisica rimane un argomento di dibattito; le discussioni offrono prospettive uniche sul tema in questione."]}),"\n",(0,n.jsx)(e.h2,{id:"do-kwon-ha-convertito-fondi-illeciti-da-luna-a-bitcoin",children:"Do Kwon ha convertito fondi illeciti da LUNA a Bitcoin"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://cointelegraph.com/news/do-kwon-converted-stolen-funds-from-luna-to-bitcoin-s-korean-prosecutors",children:"Originale"}),".\nI procuratori sudcoreani hanno identificato quasi 314,2 milioni di dollari di beni illeciti legati al cofondatore di Terraform Labs, Do Kwon, e ai suoi collaboratori, di cui il solo Kwon \xe8 collegato a circa 69 milioni di dollari. I procuratori hanno contattato Binance per bloccare qualsiasi richiesta di prelievo associata a Kwon. Kwon avrebbe convertito la maggior parte dei fondi illeciti, che ammontano a circa 414,5 miliardi di won, in Bitcoin e nessuno dei beni a lui collegati \xe8 recuperabile o sotto la giurisdizione delle autorit\xe0 sudcoreane. Terra era un ecosistema di criptovalute crollato nel maggio 2022, in cui l'ex CEO Kwon \xe8 stato accusato di aver sottratto Bitcoin per un valore di quasi 100 milioni di dollari dopo il crollo."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35499996",children:"Discussion Service"}),".\nI dati sulla catena mostrano la conversione in Bitcoin di Do Kwon di Terraform Labs dei fondi fraudolenti di LUNA. Mostra i limiti della tracciabilit\xe0 delle frodi attraverso le banche tradizionali. Gli utenti di Discussion Service discutono degli strumenti per la privacy e dell'onest\xe0 nello spazio crittografico. Si discute se l'intelligenza si sia evoluta per la competizione o per la cooperazione, e alcuni sostengono la seconda ipotesi. La competizione e la predazione spingono alla competizione, ma la tendenza generale \xe8 quella di continuare a discutere i ruoli nell'evoluzione dell'intelligenza."]}),"\n",(0,n.jsx)(e.h2,{id:"intervista-con-andrew-kelley-creatore-di-zig-2021",children:"Intervista con Andrew Kelley (creatore di Zig) (2021)"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://corecursive.com/067-zig-with-andrew-kelley/",children:"Originale"}),".\nAndrew Kelley parla della sua esperienza nello sviluppo del linguaggio di programmazione Zig, delle sfide di conciliare un lavoro a tempo pieno con il lavoro open-source, dell'importanza di negoziare la propriet\xe0 intellettuale e delle questioni morali che circondano il forking commerciale nella comunit\xe0 open-source. Zig \xe8 un linguaggio di programmazione senza scopo di lucro che mira a migliorare la sicurezza della memoria e a ridurre il sovraccarico di informazioni per gli utenti. Kelley prevede che Zig diventi il linguaggio di riferimento per i sistemi operativi e i libri di testo, con il risultato di migliorare le prestazioni delle applicazioni, l'utilizzo della memoria e la stabilit\xe0. Tech Times riferisce anche di vari corsi video di programmazione disponibili online."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35502151",children:"Discussion Service"}),".\nL'intervista di Corecursive al creatore di Zig, Andrew Kelley, ispira gli ascoltatori a scaricare tutti i podcast passati sul sito web, discutendo di progetti di crowd funding e di consigli personali nei commenti separati. Un ascoltatore apprezza l'atmosfera amichevole del canale di schema #chicken. Un altro sottolinea la trasparenza di Andrew Kelley in un caso di biforcazione di Zig, ma un utente risponde negativamente alla sua interazione con Kelley. Nel complesso, gli ascoltatori apprezzano la copertura dell'intervista su Zig e sulla storia tecnologica di SQLite."]}),"\n",(0,n.jsx)(e.h2,{id:"supavisor---un-pool-di-connessioni-postgres-scritto-in-elixir",children:"Supavisor - un pool di connessioni Postgres scritto in Elixir"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://github.com/supabase/supavisor",children:"Originale"}),".\nSupavisor \xe8 un pool di connessioni Postgres in grado di delegare milioni di connessioni Postgres dei clienti finali in un pool di connessioni native al database Postgres, attraverso un'architettura scalabile e cloud-native. Questo sistema semplifica la gestione dei cluster Postgres per i gestori di database, fornendo una facile configurazione di cluster Postgres ad alta disponibilit\xe0, e allo stesso tempo \xe8 efficiente dal punto di vista delle risorse, scalabile, multi-tenant e Cloud-native. Sono gi\xe0 disponibili benchmark e test di carico che dimostrano la capacit\xe0 di gestire un milione di connessioni Postgres su un cluster e di assorbire milioni di connessioni, rendendolo un'ottima scelta per gli sviluppatori che si connettono a Postgres da ambienti Serverless. Il lavoro futuro include il bilanciamento del carico, il pooling delle sessioni, la gestione dell'alta disponibilit\xe0 di Postgres e API come Postgres binary, HTTPS e molto altro. Jos\xe9 Valim e il team di Dashbit hanno contribuito alle decisioni di progettazione di Supavisor, che si ispira a prodotti come PgBouncer, Amazon RDS Proxy, Google Cloud SQL Proxy e altri ancora."]}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35501718",children:"Discussion Service"}),".\nIl CEO di Supabase presenta Supavisor, un connection pooler Postgres realizzato con Elixir, sottolineando la sua somiglianza con Pgbouncer e progettato per la multi-tenancy. I benchmark di Supavisor indicano che pu\xf2 gestire un elevato throughput consumando 7,8G di RAM e ~50% di CPU su una macchina a 64vCPU. Supabase prevede di avere Supavisor davanti a tutti i suoi database, scalando l'elaborazione con zero tempi di inattivit\xe0. Gli utenti di Discussion Service chiedono l'aggiunta di dichiarazioni preparate in modalit\xe0 pooling delle transazioni e suggeriscono di usare Nimble_pool piuttosto che Poolboy, mentre lodano il supporto alla concorrenza e la natura fault-tolerant di Elixir. Un utente di Discussion Service condivide l'esperienza di lavoro con Pgbouncer su 4 macchine vCPU e un altro parla del proprio pool di Pgbouncer comuni che indirizzano a varie istanze PostgreSQL utilizzando il proxy Cloud SQL di Google."]}),"\n",(0,n.jsx)(e.h2,{id:"nuove-accuse-di-plagio-contro-roy-lichtenstein",children:"Nuove accuse di plagio contro Roy Lichtenstein"}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"https://www.theguardian.com/artanddesign/2023/apr/09/new-allegations-of-plagiarism-against-roy-lichtenstein",children:"Originale"}),'.\nNuove accuse di plagio sono state rivolte a Roy Lichtenstein, con un nuovo film che sostiene che centinaia di sue opere possono essere ricondotte ad altri artisti. Il documentario sostiene che oltre 30 artisti del fumetto sono stati "appropriati" dal fondatore del movimento della pop art, che ha guadagnato milioni con la vendita delle sue opere, mentre gli artisti originali che sono stati copiati hanno vissuto una vita austera e persino indigente. Mentre alcuni difendono il lavoro di Lichtenstein come "appropriazione", i critici lo definiscono un furto, con "plagi veri e propri" citati accanto a opere "tecnicamente e artisticamente" superiori copiate da Lichtenstein.']}),"\n",(0,n.jsxs)(e.p,{children:[(0,n.jsx)(e.a,{href:"http://news.ycombinator.com/item?id=35501868",children:"Discussion Service"}),".\nLe nuove accuse di plagio nei confronti di Roy Lichtenstein scatenano un dibattito sull'etica, l'originalit\xe0 e l'adeguatezza nel mondo dell'arte. Gli utenti di Discussion Service discutono se l'opera di Lichtenstein sia una trasformazione o un palese furto con modifiche minime. Emergono problemi di copyright e di propriet\xe0 intellettuale, nonch\xe9 questioni relative al valore culturale attribuito all'arte dei fumetti rispetto all'arte di qualit\xe0. Il dibattito include opinioni sulla natura dell'arte, sulla creazione e sul valore nel mondo dell'arte. Secondo il post, gli artisti originali dei fumetti erano spesso visti come merci poco pagate."]})]})}function u(i={}){const{wrapper:e}={...(0,t.R)(),...i.components};return e?(0,n.jsx)(e,{...i,children:(0,n.jsx)(d,{...i})}):d(i)}}}]);